'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const core=require('../docs/core/payout-ledger.js'),history=require('../docs/core/commission-history.js');
const source=fs.readFileSync(path.join(__dirname,'../docs/mock-backend.js'),'utf8');
const a=source.indexOf('function ventasParaReportes(uid)'),b=source.indexOf('  const realFetch =',a);
assert.ok(a>0&&b>a);
function fixture(){const ventas=Array.from({length:5},(_,i)=>({id:'book-'+i,fecha:'2026-10-15T12:00:00Z',ubicacionId:'rack',productoId:'book',promotoraId:'artist',cantidad:1,precioUnit:15,costoUnit:1,split:{montoComisionSocio:i===4?12.75:0,montoNetoDueno:i===4?2.25:15,comisionPct:i===4?85:0,reparto:i===4?[{promotoraId:'artist',monto:12.75}]:[]}}));return {ventas,ajustesComision:ventas.slice(0,4).map(v=>({id:'adj-retro-'+v.id,tipo:'recalculo-retroactivo',ventaId:v.id,productoId:'book',ubicacionId:'rack',fecha:v.fecha,montoBruto:0,montoComisionSocio:12.75,montoNetoDueno:-12.75,reparto:[{promotoraId:'artist',monto:12.75}],comisionPct:85})),productos:[{id:'book',nombre:'book',pctAsociado:85,comisionistaId:'artist'}],ubicaciones:[{id:'rack',nombre:'rack',tipo:'socio',promotoraId:'artist'}],promotoras:[{id:'artist',nombre:'Artist'}],clientes:[],payouts:[],payoutConflicts:[]};}
function rows(e){const args={_payoutCore:()=>core,ventasActivas:()=>e.ventas.filter(v=>!v.anulada),ajustesComision:e.ajustesComision,ubicaciones:e.ubicaciones,payouts:e.payouts,payoutConflicts:e.payoutConflicts,ajusteRetencion:null,productos:e.productos,clientes:e.clientes,promotoras:e.promotoras,normPctAsociado:x=>x,nombreUbic:()=> 'rack',esDelMesActual:()=>false,fechaLocalDe:v=>String(v||'').slice(0,10)};return new Function(...Object.keys(args),source.slice(a,b)+'\nreturn ventasParaReportes();')(...Object.values(args));}
test('historical API: all five amounts from recorded ledger, immutable receipts, no implied adjustment',()=>{const e=fixture(),before=JSON.stringify(e),r=rows(e),t=history.project({sales:r,group:'comisionista'}).totals;assert.deepEqual([t.count,t.gross,t.commission],[5,75,63.75]);assert.equal(r.filter(v=>v.comisionAjusteRetroIncluido).length,4);assert.equal(r.reduce((n,v)=>n+v.netoCasa,0),11.25);assert.equal(JSON.stringify(e),before);e.ajustesComision=[];assert.equal(history.project({sales:rows(e)}).totals.commission,12.75);});
test('historical API: real nonzero split and explicit noCommission never overwritten by this repair',()=>{const e=fixture();e.ventas[0].noCommission=true;e.ventas[1].split={montoComisionSocio:7.5,montoNetoDueno:7.5,comisionPct:50,reparto:[{promotoraId:'artist',monto:7.5}]};const r=rows(e);assert.equal(r[0].comisionAsociado,0);assert.equal(r[0].comisionAjusteRetroIncluido,false);assert.equal(r[1].comisionAsociado,7.5);assert.equal(r[1].comisionAjusteRetroIncluido,false);});

